scenes=[]
def scene(name,start,duration,markup,css,js):
    scenes.append((name,start,duration))
    (P/'compositions'/f'{name}.html').write_text(f'''<template><style>@font-face{{font-family:Geist;src:url('assets/fonts/GeistMono-Latin.woff2')}}#root{{position:absolute;inset:0;overflow:hidden}}{css}</style><div id="root" data-composition-id="{name}" data-duration="{duration}" data-width="1920" data-height="1080">{markup}</div><script>(()=>{{const tl=gsap.timeline({{paused:true}});{js}window.__timelines['{name}']=tl;}})();</script></template>''')
def handles(cls='selection'):
    return f'<div class="{cls}" data-layout-ignore><i class="handle"></i><i class="handle"></i><i class="handle"></i><i class="handle"></i></div>'
